SELECT * FROM admin
role = 1
AND username LIKE CONCAT('%', #{username}, '%')
AND email LIKE CONCAT('%', #{phone}, '%')
AND status = #{status}
ORDER BY created_at DESC LIMIT #{pageSize} OFFSET #{pageNum}

